<?php

namespace App\Policies;

use App\Models\User;
use App\Services\StaffAccessGuard;
use Illuminate\Auth\Access\HandlesAuthorization;
use Illuminate\Foundation\Auth\User as AuthUser;

/**
 * Generated by Shield, then hardened by hand (Staff 0A hotfix). If
 * `shield:generate` is ever re-run for UserResource, re-apply the two
 * changes below or it will silently reopen them:
 *
 *  - Staff are never deleted: every delete ability is false for everyone,
 *    super_admin included. There is no Gate::before bypass (Shield's
 *    super_admin.define_via_gate is false), so nothing overrides this.
 *  - Accounts holding super_admin or ceo can only be viewed for editing
 *    by holders of assign_staff_roles (StaffAccessGuard::canManage).
 */
class UserPolicy
{
    use HandlesAuthorization;

    public function viewAny(AuthUser $authUser): bool
    {
        return $authUser->can('ViewAny:User');
    }

    public function view(AuthUser $authUser, User $user): bool
    {
        return $authUser->can('View:User');
    }

    public function create(AuthUser $authUser): bool
    {
        return $authUser->can('Create:User');
    }

    public function update(AuthUser $authUser, User $user): bool
    {
        return $authUser->can('Update:User')
            && StaffAccessGuard::canManage($authUser instanceof User ? $authUser : null, $user);
    }

    public function delete(AuthUser $authUser, ?User $user = null): bool
    {
        return false;
    }

    public function deleteAny(AuthUser $authUser): bool
    {
        return false;
    }

    public function restore(AuthUser $authUser): bool
    {
        return $authUser->can('Restore:User');
    }

    public function forceDelete(AuthUser $authUser, ?User $user = null): bool
    {
        return false;
    }

    public function forceDeleteAny(AuthUser $authUser): bool
    {
        return false;
    }

    public function restoreAny(AuthUser $authUser): bool
    {
        return $authUser->can('RestoreAny:User');
    }

    public function replicate(AuthUser $authUser): bool
    {
        return $authUser->can('Replicate:User');
    }

    public function reorder(AuthUser $authUser): bool
    {
        return $authUser->can('Reorder:User');
    }
}
